contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test SetMinSum behavior when contract not initialized: it must either revert and leave state unchanged,
    // or succeed and set MinSum to the provided value; in both cases address(c).balance must not change.
    function run(uint newMin) public payable {
        // Observe before values
        uint beforeMin = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Call SetMinSum (non-payable) and capture whether it reverted
        bool setReverted;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        // Observe after values
        uint afterMin = c.MinSum(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // Assert the general rule
        assert(
            // If it reverted, MinSum and balance unchanged
            (setReverted && afterMin == beforeMin && afterBal == beforeBal)
            // If it didn't revert, MinSum equals newMin and balance unchanged
            || (!setReverted && afterMin == newMin && afterBal == beforeBal)
        );
    }

    receive() external payable {}
}

